rss.channel:
{{ site.title | xml_escape }}
{{ site.jackal.feed_description | default: site.rss-description | default: site.description | default: site.title | xml_escape }}
{{ '/' | absolute_url | xml_escape }}

{% assign excerpt_length = site.jackal.feed_excerpt_length | default: site.excerpt_length | default: 50 %}
{% for post in site.posts limit: 20 %}
  {% assign post_url = post.url | absolute_url | xml_escape %}


    {{ post.title | strip_html | xml_escape }}
    {{ post_url }}
    {{ post_url }}
    {{ post.date | date_to_rfc822 }}

      {% if post.subtitle %}{{ post.subtitle | strip_html | xml_escape }} - {% endif %}
      {{ post.content | strip_html | normalize_whitespace | truncatewords: excerpt_length | xml_escape }}


{% endfor %}
